}

/* iOS Timer Scroll Picker Styles */
.select-wrap {
    position: relative;
    height: 100%;
    text-align: center;
    overflow: hidden;
    font-size: 16px;
    color: #666;
}

.select-options {
    position: absolute;
    top: 50%;
    left: 0;
    width: 100%;
    transform-style: preserve-3d;
    margin: 0 auto;
    display: block;
    transform: translateZ(-60px) rotateX(0deg);
    list-style: none;
    padding: 0;
}

.select-option {
    position: absolute;
    top: 0;
    left: 0;
    width: 100%;
    height: 30px;
